<?php
require __DIR__.'/bootstrap.php'; admin_require_login();
$pdo=admin_db(); $message=$_SESSION['admin_flash']??''; unset($_SESSION['admin_flash']);
$destinations=$pdo->query('SELECT id,name,slug,image_url FROM destinations ORDER BY sort_order,name')->fetchAll();
$siteImages=$pdo->query('SELECT * FROM site_images ORDER BY label')->fetchAll();
$counts=$pdo->query('SELECT destination_id,COUNT(*) AS total FROM destination_images GROUP BY destination_id')->fetchAll(PDO::FETCH_KEY_PAIR);
$selected=(int)($_GET['destination_id']??($destinations[0]['id']??0));
$chosen=null; foreach($destinations as $d){if((int)$d['id']===$selected){$chosen=$d;break;}}
$gallery=[]; if($chosen){$q=$pdo->prepare('SELECT * FROM destination_images WHERE destination_id=? ORDER BY sort_order,id');$q->execute([$selected]);$gallery=$q->fetchAll();}
function wi_image_url(PDO $pdo,string $input): string {
 $input=trim($input);
 if($input==='') throw new RuntimeException('Choose an image or enter an image URL.');
 if(filter_var($input,FILTER_VALIDATE_URL)){if(!in_array(strtolower((string)parse_url($input,PHP_URL_SCHEME)),['http','https'],true))throw new RuntimeException('Only HTTP or HTTPS image URLs are accepted.');return $input;}
 throw new RuntimeException('Invalid image URL.');
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  admin_verify_csrf(); $action=$_POST['action']??'';
  if($action==='save_site'){
   $key=trim((string)($_POST['image_key']??''));$label=trim((string)($_POST['label']??''));$url=wi_image_url($pdo,(string)($_POST['image_url']??''));$alt=trim((string)($_POST['alt_text']??''));
   if(!preg_match('/^[a-z0-9._-]{2,120}$/',$key)||$label==='')throw new RuntimeException('Invalid image section.');
   $s=$pdo->prepare('INSERT INTO site_images(image_key,label,image_url,alt_text) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE label=VALUES(label),image_url=VALUES(image_url),alt_text=VALUES(alt_text)');$s->execute([$key,$label,$url,$alt]);$_SESSION['admin_flash']='Website image saved.';
  } elseif($action==='save_destination_main'){
   $id=(int)($_POST['destination_id']??0);$url=wi_image_url($pdo,(string)($_POST['image_url']??''));$s=$pdo->prepare('UPDATE destinations SET image_url=? WHERE id=?');$s->execute([$url,$id]);$_SESSION['admin_flash']='Destination main image updated.';
  } elseif($action==='add_destination_image'){
   $id=(int)($_POST['destination_id']??0);$url=wi_image_url($pdo,(string)($_POST['image_url']??''));$alt=trim((string)($_POST['alt_text']??''));$q=$pdo->prepare('SELECT COUNT(*) FROM destination_images WHERE destination_id=?');$q->execute([$id]);$count=(int)$q->fetchColumn();
   if($count>=9)throw new RuntimeException('This destination already has 10 images including its main image. Remove one before adding another.');
   $s=$pdo->prepare('INSERT INTO destination_images(destination_id,image_url,alt_text,sort_order) VALUES(?,?,?,?)');$s->execute([$id,$url,$alt,$count+1]);$_SESSION['admin_flash']='Destination gallery image added.';
  } elseif($action==='delete_destination_image'){
   $id=(int)($_POST['image_id']??0);$pdo->prepare('DELETE FROM destination_images WHERE id=?')->execute([$id]);$_SESSION['admin_flash']='Destination gallery image removed.';
  } elseif($action==='move_destination_image'){
   $id=(int)($_POST['image_id']??0);$dir=($_POST['direction']??'up')==='down'?'down':'up';$q=$pdo->prepare('SELECT id,destination_id,sort_order FROM destination_images WHERE id=?');$q->execute([$id]);$row=$q->fetch();
   if($row){$op=$dir==='up'?'<':'>';$order=$dir==='up'?'DESC':'ASC';$n=$pdo->prepare("SELECT id,sort_order FROM destination_images WHERE destination_id=? AND sort_order $op ? ORDER BY sort_order $order,id $order LIMIT 1");$n->execute([$row['destination_id'],$row['sort_order']]);$other=$n->fetch();if($other){$pdo->beginTransaction();$pdo->prepare('UPDATE destination_images SET sort_order=? WHERE id=?')->execute([$other['sort_order'],$row['id']]);$pdo->prepare('UPDATE destination_images SET sort_order=? WHERE id=?')->execute([$row['sort_order'],$other['id']]);$pdo->commit();}}
   $_SESSION['admin_flash']='Destination image order updated.';
  }
 }catch(Throwable $e){$_SESSION['admin_flash']='Could not save: '.$e->getMessage();}
 $redirect='website-images.php'; if(!empty($_POST['destination_id']))$redirect.='?destination_id='.(int)$_POST['destination_id']; header('Location: '.$redirect);exit;
}
