</style></head><body class="admin-shell"><aside class="admin-sidebar"><a class="admin-brand" href="../index.html">WINTRIP <span>SAFARIS</span></a><p>WEBSITE MANAGEMENT</p><a href="dashboard.php">▧ &nbsp; Gallery Manager</a><a class="selected" href="website-images.php">▣ &nbsp; Website Images</a><a href="../gallery.php" target="_blank">▦ &nbsp; View Public Gallery ↗</a><a href="../index.html" target="_blank">⌂ &nbsp; View Website ↗</a><form method="post" action="logout.php"><input type="hidden" name="csrf" value="<?=admin_h(admin_csrf())?>"><button class="logout-button">↪ &nbsp; Sign out</button></form></aside><main class="admin-main manager-wrap"><header class="admin-top"><div><span>WINTRIP SAFARIS / ADMIN</span><h1>Website Image Manager</h1><p class="manager-intro">Manage homepage imagery and destination photographs from one place.</p></div><div class="admin-user"><?=admin_h($_SESSION['admin_email']??'Administrator')?></div></header><?php if($message): ?><div class="admin-success"><?=admin_h($message)?></div><?php endif; ?>
<section class="admin-panel"><h2>Homepage & website sections</h2><p class="manager-note">Paste a full image URL. The section keys below connect to the homepage. Saving a key updates that image wherever it is used.</p><div class="manager-grid"><?php $slots=[['home.hero.1','Homepage hero image 1'],['home.hero.2','Homepage hero image 2'],['home.hero.3','Homepage hero image 3'],['home.about.large','About section large image'],['home.about.small','About section small image'],['home.testimonial','Testimonials background'],['home.journal.1','Journal image 1'],['home.journal.2','Journal image 2'],['home.journal.3','Journal image 3'],['home.gallery.1','Homepage gallery image 1'],['home.gallery.2','Homepage gallery image 2'],['home.gallery.3','Homepage gallery image 3'],['home.gallery.4','Homepage gallery image 4'],['home.gallery.5','Homepage gallery image 5']];$map=[];foreach($siteImages as $si)$map[$si['image_key']]=$si;foreach($slots as $slot):$existing=$map[$slot[0]]??null;?><article class="manager-card"><h3><?=admin_h($slot[1])?></h3><?php if($existing): ?><img src="<?=admin_h($existing['image_url'])?>" alt="Current image"><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=admin_h(admin_csrf())?>"><input type="hidden" name="action" value="save_site"><input type="hidden" name="image_key" value="<?=admin_h($slot[0])?>"><input type="hidden" name="label" value="<?=admin_h($slot[1])?>"><label>Image URL<input type="url" name="image_url" required value="<?=admin_h($existing['image_url']??'')?>" placeholder="https://..."></label><label>Alt text<input name="alt_text" value="<?=admin_h($existing['alt_text']??'')?>"></label><button type="submit">Save image</button></form></article><?php endforeach; ?></div></section>
<section class="admin-panel"><div class="manager-top"><div><h2>Destination images</h2><p class="manager-note">Each destination supports one main image plus up to nine additional images: 10 total.</p></div><form method="get"><select name="destination_id" onchange="this.form.submit()"><?php foreach($destinations as $d): ?><option value="<?=(int)$d['id']?>" <?=$selected===(int)$d['id']?'selected':''?>><?=admin_h($d['name'])?></option><?php endforeach; ?></select></form></div><?php if($chosen): ?><div class="manager-card"><h3><?=admin_h($chosen['name'])?> — main image</h3><?php if($chosen['image_url']): ?><img src="<?=admin_h($chosen['image_url'])?>" alt="<?=admin_h($chosen['name'])?>"><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=admin_h(admin_csrf())?>"><input type="hidden" name="action" value="save_destination_main"><input type="hidden" name="destination_id" value="<?=$selected?>"><label>Main image URL<input type="url" name="image_url" value="<?=admin_h($chosen['image_url']??'')?>" required></label><button type="submit">Save main image</button></form></div><div class="manager-card"><h3>Add destination gallery image (<?=1+count($gallery)?>/10)</h3><form method="post"><input type="hidden" name="csrf" value="<?=admin_h(admin_csrf())?>"><input type="hidden" name="action" value="add_destination_image"><input type="hidden" name="destination_id" value="<?=$selected?>"><label>Image URL<input type="url" name="image_url" placeholder="https://..." required></label><label>Image description<input name="alt_text" maxlength="255"></label><button type="submit" <?=count($gallery)>=9?'disabled':''?>>Add image</button></form></div><div class="manager-grid"><?php foreach($gallery as $image): ?><article class="manager-photo"><img src="<?=admin_h($image['image_url'])?>" alt="<?=admin_h($image['alt_text']??'')?>"><p><?=admin_h($image['alt_text']??'Destination photograph')?></p><div class="manager-actions"><?php foreach(['up','down'] as $dir): ?><form method="post"><input type="hidden" name="csrf" value="<?=admin_h(admin_csrf())?>"><input type="hidden" name="action" value="move_destination_image"><input type="hidden" name="destination_id" value="<?=$selected?>"><input type="hidden" name="image_id" value="<?=(int)$image['id']?>"><input type="hidden" name="direction" value="<?=$dir?>"><button type="submit"><?=$dir==='up'?'↑':'↓'?></button></form><?php endforeach; ?><form method="post" onsubmit="return confirm('Remove this destination image?')"><input type="hidden" name="csrf" value="<?=admin_h(admin_csrf())?>"><input type="hidden" name="action" value="delete_destination_image"><input type="hidden" name="destination_id" value="<?=$selected?>"><input type="hidden" name="image_id" value="<?=(int)$image['id']?>"><button type="submit">Remove</button></form></div></article><?php endforeach; ?></div><?php else: ?><p>No destinations found.</p><?php endif; ?></section><footer class="admin-footer">© 2026 Wintrip Safaris Limited · Private administration area</footer></main></body></html>
